/* Campaign operations use authoritative receipts; roster originals are never inferred from labels. */
(()=>{'use strict';
const E=value=>esc(String(value??'')),L=(en,ko)=>`<span data-i18n-en="${E(en)}" data-i18n-ko="${E(ko)}">${E(en)}</span>`,T=(en,ko)=>window.UKI18n?.language==='en'?en:ko,copy=value=>structuredClone(value);
const locks=new Set(),cachedReceipts=new Map();let queued=false;
const account=()=>window.AccountParity?.account?.id||'';
const cycle=c=>Number.isSafeInteger(Number(c?.currentCycle))&&Number(c.currentCycle)>0?Number(c.currentCycle):1;
function state(c){return c?.automation||{version:1,challenges:[],cycleRecords:{},receipts:[],deadlines:{},announcements:[]};}
function canEdit(c){return !!c&&data.campaigns.includes(c)&&c.phase!=='Closed'&&!!window.MMCampaignSessionData?.canEdit(c);}
function canManageOwn(c,spec={}){const own=window.MMCampaignOwnership;if(!c||!data.campaigns.includes(c)||!own?.ownGangs(c).length)return false;return (spec.gangIds||[]).every(id=>own.canManage(c,id));}
function phase(c){const scheduled=window.MMCampaignSchedule?.info(c);if(scheduled)return scheduled.complete?'Completed':scheduled.stage.name;return null;}
function die(sides=6){if(!Number.isSafeInteger(sides)||sides<1||sides>2000)throw Error('Invalid die');const bytes=new Uint32Array(1),ceiling=Math.floor(4294967296/sides)*sides;do{crypto.getRandomValues(bytes);}while(bytes[0]>=ceiling);return bytes[0]%sides+1;}
const receipts=c=>[...(cachedReceipts.get(c.remoteCampaignId||c.id)||[]),...(state(c).receipts||[])].filter((r,i,a)=>a.findIndex(x=>x.id===r.id||x.operationKey&&x.operationKey===r.operationKey)===i);
function getReceipt(c,key){return receipts(c).find(r=>{const k=r.operationKey||r.key;return(k===key||k?.startsWith(key+':redo:'))&&!r.reversedAt&&!r.reversed;});}
async function operationKey(key){if(typeof key!=='string'||!key)throw Error('Invalid operation key');if(key.length<=100)return key;const bytes=new TextEncoder().encode(key),hash=await crypto.subtle.digest('SHA-256',bytes);return 'sha256:'+Array.from(new Uint8Array(hash),b=>b.toString(16).padStart(2,'0')).join('');}
function notify(message,error=false){let node=document.querySelector('[data-ca-notice]');if(!node){node=document.createElement('p');node.dataset.caNotice='';node.className='ca-notice';node.setAttribute('role',error?'alert':'status');document.querySelector('.content')?.prepend(node);}node.textContent=message;node.classList.toggle('is-error',error);node.setAttribute('role',error?'alert':'status');}
function modal(title,fields,submit,callback){cpModal(title,fields,submit,callback);document.querySelector('.modal')?.classList.add('ca-modal');window.UKI18n?.refresh(document.querySelector('.modal-bg'));}
const button=(module,action,en,ko,extra='',kind='')=>`<button type="button" class="btn ${kind}" data-ca-module="${E(module)}" data-ca-action="${E(action)}" ${extra}>${L(en,ko)}</button>`;
const timeRemaining=c=>{const until=state(c).deadlines?.[String(cycle(c))]?.battle;return until?Date.now()<Date.parse(until):null;};
function coreSnapshot(value){return JSON.stringify({gangs:value.gangs,campaigns:value.campaigns,customAssets:value.customAssets,skirmishes:value.skirmishes});}
function canonicalize(value,mapping,key=''){
 if(Array.isArray(value))return value.map(v=>canonicalize(v,mapping,key));
 if(value&&typeof value==='object'){const result=Object.fromEntries(Object.entries(value).map(([k,v])=>[k,canonicalize(v,mapping,k)]));if(value.campaignCaptureId){const holder=data.gangs.find(g=>(g.campaignCaptives||[]).some(r=>r.id===value.campaignCaptureId));if(holder){const holderId=mapping.get(holder.id)||holder.remoteSnapshotId||holder.id;for(const field of ['capturedBy','captured_by_gang_id'])if(Object.hasOwn(value,field))result[field]=holderId;}}return result;}
 if(typeof value==='string'&&mapping.has(value)&&!['sourceGangId','source_gang_id'].includes(key)&&(/gang_?ids?$/i.test(key)||['attacker','defender','winner','winners','claimedBy','claimedByGangId','controlledBy','gangA','gangB','holderId','targetId','stakeOwnerBefore','challenger','opponent','capturedBy','captured_by_gang_id'].includes(key)))return mapping.get(value);
 return value;
}
async function mappingFor(c){const mapping=new Map(data.gangs.map(g=>[g.id,g.remoteSnapshotId||g.id]));if(!(c.remoteOwnerId||c.remoteCampaignId||c.remoteRevision))return mapping;
 const remote=await window.AccountParity.api('/campaigns/'+encodeURIComponent(c.remoteCampaignId||c.id));
 for(const incoming of remote.snapshot?.gangs||[]){const owner=incoming.sourceOwnerId||incoming.remoteOwnerId||remote.ownerId,sourceId=incoming.sourceGangId||incoming.id;const local=data.gangs.find(g=>g.remoteSnapshotId===incoming.id)||data.gangs.find(g=>!g.remoteReadOnly&&owner===account()&&g.id===sourceId)||data.gangs.find(g=>g.id===incoming.id);if(local)mapping.set(local.id,incoming.id);}
 return mapping;
}
function consentAllowed(c,intent){if(!['ransom-accept','ransom-decline','source-ack'].includes(intent?.kind)||!account())return false;return data.campaigns.includes(c)&&!window.AccountParity?.connecting&&!window.AccountParity?.busy&&window.AccountParity?.ready;}
function diff(before,after,path=[],out=[]){
 if(JSON.stringify(before)===JSON.stringify(after))return out;
 if(before&&after&&!Array.isArray(before)&&!Array.isArray(after)&&typeof before==='object'&&typeof after==='object'){for(const k of new Set([...Object.keys(before),...Object.keys(after)]))diff(before[k],after[k],[...path,k],out);return out;}
 out.push({path,before:before===undefined?null:copy(before),after:after===undefined?null:copy(after),beforeExists:before!==undefined,afterExists:after!==undefined});return out;
}
function replace(target,value){for(const key of Object.keys(target))if(!Object.hasOwn(value,key))delete target[key];Object.assign(target,value);}
function withoutAudit(value){const result=copy(value);if(result.campaign?.automation)delete result.campaign.automation.receipts;return result;}
function at(root,path){return path.reduce((v,k)=>v?.[k],root);}
function write(root,patch,side){let node=root;for(const key of patch.path.slice(0,-1)){if(!node[key]||typeof node[key]!=='object')node[key]={};node=node[key];}const last=patch.path.at(-1);if(patch[side+'Exists'])node[last]=copy(patch[side]);else delete node[last];}
async function apply(c,spec){
 const owner=account(),cid=c?.id;if(!spec?.key||!spec.label)throw Error(T('An operation key and label are required.','작업 식별자와 이름이 필요합니다.'));
 const baseKey=await operationKey(spec.key);spec={...spec,key:baseKey};
 if(!canEdit(c)&&!(spec.intent?.kind==='campaign-settings'&&window.MMCampaignPermissions?.canArbitrate(c))&&!canManageOwn(c,spec)&&!consentAllowed(c,spec.intent))throw Error(T('Your access no longer permits this operation.','현재 권한으로 이 작업을 처리할 수 없습니다.'));
 if(locks.has(cid))throw Error(T('Wait for the current operation to finish.','진행 중인 작업이 끝날 때까지 기다리세요.'));
 if(getReceipt(c,spec.key)){notify(T('This operation is already recorded.','이미 처리한 작업입니다.'));return {replayed:true};}
 locks.add(cid);refresh();
 try{
  let revision=null;if(owner)revision=await window.AccountParity.ensureSynced();
  if(owner&&!cachedReceipts.has(c.remoteCampaignId||c.id))await loadReceipts(c);if(getReceipt(c,baseKey)){notify(T('This operation is already recorded.','이미 처리한 작업입니다.'));return {replayed:true};}const reversed=receipts(c).find(r=>{const k=r.operationKey||r.key;return(k===baseKey||k?.startsWith(baseKey+':redo:'))&&(r.reversedAt||r.reversed);});if(reversed)spec.key=baseKey+':redo:'+reversed.id;
  if(account()!==owner||!data.campaigns.includes(c))throw Error(T('Records changed. Reopen this operation.','기록이 변경되었습니다. 작업 창을 다시 여세요.'));
  const baseline={accountId:owner,collections:coreSnapshot(data)},before={campaign:copy(c),gangs:copy(data.gangs)},after=copy(before);
  after.campaign.automation??=copy(state(c));const result=spec.mutate?.(after);if(result&&typeof result.then==='function')throw Error('Operation preparation must be synchronous');
  const allowed=new Set(spec.gangIds||[]),changed=before.gangs.filter((g,i)=>JSON.stringify(g)!==JSON.stringify(after.gangs[i])).map(g=>g.id);
  if(changed.some(id=>!allowed.has(id))||after.gangs.length!==before.gangs.length)throw Error(T('The operation changed an undeclared roster.','선택하지 않은 갱의 명단이 바뀌어 저장을 중단했습니다.'));
  const selected=[...new Set([...allowed,...changed])],localBefore={campaign:before.campaign,gangs:before.gangs.filter(g=>selected.includes(g.id))},localAfter={campaign:after.campaign,gangs:after.gangs.filter(g=>selected.includes(g.id))};
  if(owner){
   const mapping=await mappingFor(c);if(account()!==owner||coreSnapshot(data)!==baseline.collections)throw Error(T('Records changed while preparing. Reopen the operation.','준비 중 기록이 변경되었습니다. 작업 창을 다시 여세요.'));
   const serverId=c.remoteCampaignId||c.id,convert=x=>{const v=canonicalize(x,mapping);v.campaign.id=serverId;v.gangs=v.gangs.map(g=>({...g,id:mapping.get(g.id)||g.id}));return v;};let response;
   if(consentAllowed(c,spec.intent)){
    const intent=canonicalize(spec.intent,mapping),decision=intent.kind==='ransom-accept'?'accept':intent.kind==='ransom-decline'?'decline':'acknowledge';
    response=await window.AccountParity.api('/campaigns/'+encodeURIComponent(serverId)+'/automation/consent',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({operationKey:spec.key,documentRevision:revision,holderId:intent.holderId,recordId:intent.recordId,offerId:intent.offerId,decision})});
   }else response=await window.AccountParity.api('/campaigns/'+encodeURIComponent(serverId)+'/automation',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({operationKey:spec.key,label:spec.label,documentRevision:revision,...(c.remoteRevision?{expectedCampaignRevision:c.remoteRevision}:{}),before:convert(localBefore),after:convert(localAfter),...(spec.intent?{intent:canonicalize(spec.intent,mapping)}:{})})});
   if(account()!==owner)return response;
   if(response.document&&window.AccountParity.acceptAutomation)window.AccountParity.acceptAutomation(response,baseline);
   else await window.AccountParity.refreshDocument();
   if(c.remoteOwnerId&&c.remoteOwnerId!==owner)await window.AccountParity.refreshShared(serverId,{navigate:false});
   if(response.receipt){const list=cachedReceipts.get(serverId)||[];cachedReceipts.set(serverId,[response.receipt,...list.filter(r=>r.id!==response.receipt.id)]);}
   notify(T('Operation recorded.','처리를 완료했습니다.'));render();return response;
  }
  if(localAfter.gangs.some(g=>g.remoteOwnerId||g.remoteReadOnly)||c.remoteOwnerId)throw Error(T('Connect your account to update shared originals.','다른 플레이어의 갱 명단을 갱신하려면 로그인하세요.'));
  const changes=diff(withoutAudit(localBefore),withoutAudit(localAfter)),receipt={id:id(),operationKey:spec.key,label:spec.label,actor:'local',at:now(),cycle:cycle(c),changes,local:true};
  replace(c,localAfter.campaign);for(const g of localAfter.gangs)replace(data.gangs.find(x=>x.id===g.id),g);c.automation??=copy(state(c));c.automation.receipts??=[];c.automation.receipts.unshift(receipt);save();notify(T('Operation recorded locally.','저장했습니다.'));return {receipt};
 }catch(error){if(!spec.errorTarget?.isConnected)notify(error.message||String(error),true);throw error;}finally{locks.delete(cid);refresh();}
}
async function reverse(c,receiptId){
 if(!canEdit(c)&&!canManageOwn(c)||locks.has(c.id))return;locks.add(c.id);refresh();try{
  const owner=account(),receipt=receipts(c).find(r=>r.id===receiptId);if(!receipt)throw Error(T('Receipt is no longer available.','정산 내역을 찾을 수 없습니다.'));
  if(receipt.reversedAt||receipt.reversed)throw Error(T('This receipt has already been reversed.','이미 취소한 정산입니다.'));
  if(owner){const revision=await window.AccountParity.ensureSynced(),baseline={accountId:owner,collections:coreSnapshot(data)},serverId=c.remoteCampaignId||c.id,result=await window.AccountParity.api('/campaigns/'+encodeURIComponent(serverId)+'/automation/'+encodeURIComponent(receiptId)+'/reverse',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({documentRevision:revision,...(c.remoteRevision?{expectedCampaignRevision:c.remoteRevision}:{})})});
   if(window.AccountParity.acceptAutomation&&result.document)window.AccountParity.acceptAutomation(result,baseline);else await window.AccountParity.refreshDocument();if(c.remoteOwnerId&&c.remoteOwnerId!==owner)await window.AccountParity.refreshShared(serverId,{navigate:false});cachedReceipts.delete(serverId);await loadReceipts(c);render();return;
  }
  const current={campaign:copy(c),gangs:data.gangs.filter(g=>receipt.changes.some(p=>p.path[0]==='gangs')||false).map(copy)};
  const original=receipt.changes.find(p=>p.path[0]==='gangs');if(original){current.gangs=copy(original.after);for(let i=0;i<current.gangs.length;i++)current.gangs[i]=copy(data.gangs.find(g=>g.id===current.gangs[i].id)||current.gangs[i]);}
  if(current.campaign.automation)delete current.campaign.automation.receipts;
  for(const patch of receipt.changes)if(JSON.stringify(at(current,patch.path))!==JSON.stringify(patch.afterExists?patch.after:undefined))throw Error(T('Later changes overlap this receipt. Review them before reversing.','후속 변경이 이 정산과 겹칩니다. 변경 내역을 확인한 뒤 취소하세요.'));
  for(const patch of receipt.changes)write(current,patch,'before');const history=copy(c.automation.receipts);replace(c,current.campaign);c.automation??=copy(state(c));c.automation.receipts=history.map(r=>r.id===receiptId?{...r,reversedAt:now(),reversedBy:'local'}:r);for(const g of current.gangs)if(data.gangs.some(x=>x.id===g.id))replace(data.gangs.find(x=>x.id===g.id),g);save();notify(T('A reversal was recorded.','정산을 취소했습니다.'));
 }catch(error){notify(error.message,true);throw error;}finally{locks.delete(c.id);refresh();}
}
async function loadReceipts(c){if(!account())return;const owner=account(),serverId=c.remoteCampaignId||c.id;try{const result=await window.AccountParity.api('/campaigns/'+encodeURIComponent(serverId)+'/automation');if(owner===account())cachedReceipts.set(serverId,result.receipts||[]);refresh();}catch(error){if(error.status!==404)notify(error.message,true);}}
function receiptLabel(r){const original=String(r.label||''),legacy={'캠페인 도전 발행':'캠페인 도전 신청','도전 발행':'도전 신청','모집·승격 택틱 생성':'모집·승급 보상 택틱 뽑기','증원 도착 기록':'증원 배치','완료된 구출 반영':'구출 완료 처리','생포 원본 소유자 결정':'생포 확인·몸값 협상'},label=legacy[original]||original,dict=window.UK_UI_STRINGS;if(r.operationKey&&(/^(?:income|postcycle|update-roster|starting|downtime|tactics|promotion|cycle|schedule|battle|preparation|challenge|trade|ransom|rescue|captiv|manual-join)/.test(r.operationKey))&&(dict?.enToKo?.[label]||dict?.koToEn?.[label])){const en=dict.koToEn[label]||label;return L(en,dict.enToKo[en]||label);}return `<span data-user-text>${E(label===original?original:label)}</span>`;}
function showReceipts(c){loadReceipts(c).then(()=>{const rows=receipts(c);modal(T('Settlement history','정산 이력'),`<div class="wide ca-receipts">${rows.length?rows.map(r=>`<article><strong>${receiptLabel(r)}</strong><small>${E(r.at||r.createdAt||'')} · ${E(r.actor||r.actorId||'')} · ${L('Cycle','사이클')} ${E(r.cycle||'—')}</small><p>${r.reversedAt||r.reversed?L('Reversed · original receipt retained','정산 취소됨 · 이전 내역 보관'):L('Applied once','정산 완료')}</p>${button('core','reverse','Reverse','정산 취소',`data-ca-id="${E(r.id)}" ${(!canEdit(c)&&r.actor!==account()&&r.actorId!==account())||r.reversedAt||r.reversed?'disabled':''}`,'small')}</article>`).join(''):L('No automation settlements yet.','아직 자동화 정산 이력이 없습니다.')}</div>`,T('Close','닫기'),()=>true);document.querySelector('#modal-cancel').hidden=true;});}
function deadlineDialog(c){if(!window.MMCampaignPermissions?.canArbitrate(c))return false;const saved=state(c).deadlines?.[String(cycle(c))]||{},iso=stamp=>{if(!stamp)return '';const d=new Date(stamp);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)};modal(T('Cycle deadlines','사이클 마감'),`<p class="wide">${L('Choose dates, then save. Reminders and cycle progression are separate actions.','날짜를 선택해 저장하세요. 알림과 사이클 진행은 별도 동작입니다.')}</p>${[['challenge','Challenge deadline','도전 마감'],['battle','Battle deadline','전투 마감'],['report','Report deadline','보고 마감']].map(([key,en,ko])=>`<label>${L(en,ko)}<input type="datetime-local" name="${key}" value="${E(iso(saved[key]))}"></label>`).join('')}<label class="checkline wide"><input type="checkbox" name="autoAdvance" value="yes" ${saved.autoAdvance?'checked':''}>${L('When this app is open, advance after all results are resolved and the report deadline passes.','앱이 열려 있을 때 결과가 모두 처리되고 보고 마감이 지나면 다음 사이클로 진행')}</label>`,'Save',async v=>{
 const dates={};for(const key of ['challenge','battle','report']){if(v[key]){const n=Date.parse(v[key]);if(!Number.isFinite(n))throw Error(T('Choose valid dates.','유효한 날짜를 선택하세요.'));dates[key]=new Date(n).toISOString();}}if(dates.challenge&&dates.battle&&dates.challenge>dates.battle||dates.battle&&dates.report&&dates.battle>dates.report)throw Error(T('Use challenge → battle → report order.','도전 → 전투 → 보고 순서로 마감을 정하세요.'));
 const count=(state(c).deadlineRevision||0)+1;return apply(c,{key:`deadlines:${cycle(c)}:${count}`,label:'Cycle deadlines updated',gangIds:[],mutate:({campaign:d})=>{d.automation.deadlines??={};d.automation.deadlines[String(cycle(c))]={...dates,autoAdvance:v.autoAdvance==='yes'};d.automation.deadlineRevision=count;}});
 });}
function reminders(c){const deadlines=state(c).deadlines?.[String(cycle(c))]||{},nowMs=Date.now();return [['challenge','Challenge deadline','도전 마감'],['battle','Battle deadline','전투 마감'],['report','Report deadline','보고 마감']].filter(([key])=>deadlines[key]).map(([key,en,ko])=>({key,en,ko,at:deadlines[key],due:Date.parse(deadlines[key])<=nowMs}));}
function announce(c){if(!window.MMCampaignPermissions?.canArbitrate(c))return false;if((state(c).announcements||[]).some(a=>a.cycle===cycle(c))){notify(T('This cycle already has an announcement.','이 사이클은 이미 공지했습니다.'));return;}const order=state(c).cycleRecords?.[String(cycle(c))]?.order||[];return apply(c,{key:'announcement:'+cycle(c),label:'Cycle announcement published',gangIds:[],mutate:({campaign:d})=>{d.automation.announcements??=[];d.automation.announcements.push({id:id(),cycle:cycle(c),at:now(),actor:account(),text:`Cycle ${cycle(c)} · ${phase(c)||'Manual'} · ${order.map(p=>p.playerId).join(' → ')}`,deadlines:copy(state(c).deadlines?.[String(cycle(c))]||{})});}});}
// Short task notes are optional disclosures so the controls stay easy to scan.
function moduleNote(key){const notes={battle:['Battle steps','전투는 어떤 순서로 하나요?','Create a battle, choose the mission and crew, then start. After playing, enter the result and review changes before settlement.','전투를 만들고 미션·크루를 정한 뒤 시작합니다. 실제 전투 후 결과를 입력하고, 변경 내용을 확인해 정산하세요.'],economy:['Income and recovery steps','수입·회복은 언제 처리하나요?','After the cycle’s battles, resolve each gang’s post-cycle actions, collect income, then update its roster. Each control follows that order.','해당 사이클의 전투가 끝나면 갱별로 종료 후 행동 → 수입 받기 → 명단 정리 순서로 처리합니다. 각 버튼도 이 순서에 맞춰 열립니다.'],operations:['Trading and captive actions','거래·포로·지도에서 무엇을 하나요?','Choose equipment and its recipient in the cart. Captive actions appear for the relevant player; the map shows recorded territory ownership.','장바구니에서 장비와 받을 대상을 정합니다. 포로 처리 버튼은 해당 플레이어에게 표시되며, 지도에서는 기록된 영토 소유권을 확인합니다.']}[key];return notes?`<details class="ca-help"><summary><span class="ca-help-mark" aria-hidden="true">?</span>${L(notes[0],notes[1])}</summary><div class="ca-help-body"><p>${L(notes[2],notes[3])}</p></div></details>`:'';}
function panel(c){const editable=!!window.MMCampaignPermissions?.canArbitrate(c),s=state(c),alerts=reminders(c),announcements=(s.announcements||[]).slice(-1);return `<section class="card ca-console" data-ca-console="${E(c.id)}"><div class="section-heading"><div><small class="ca-kicker">${L('CAMPAIGN OPERATIONS','캠페인 운영 도구')}</small><h2>${L('Campaign progress assistant','캠페인 진행 도우미')}</h2></div><div class="actions">${button('core','deadlines','Deadlines','일정·마감',editable?'':'disabled','small')}${button('core','receipts','Settlement history','정산 이력','','small')}</div></div><p>${L('Set opponents, prepare battles, then record results and income.','상대를 정하고 전투를 준비한 뒤, 결과와 수입을 처리하세요.')}</p>${!window.MMCampaignSchedule?.info(c)?`<div class="ca-warning">${L('Configure progression to use phase-dependent automation.','단계별 자동화를 사용하려면 진행 방식을 설정하세요.')}<button type="button" class="btn small" data-campaign-schedule="configure" data-campaign-id="${E(c.id)}" ${editable?'':'disabled'}>${L('Set progression','진행 방식 설정')}</button></div>`:''}${alerts.length?`<div class="ca-reminders" role="status">${alerts.map(a=>`<span class="${a.due?'is-due':''}">${L(a.en,a.ko)} · ${E(new Date(a.at).toLocaleString(window.UKI18n?.language==='en'?'en-GB':'ko-KR'))}${a.due?' · '+L('Overdue','마감 지남'):''}</span>`).join('')}</div>`:''}${announcements.map(a=>`<details class="ca-announcement"><summary>${L('Latest cycle announcement','최근 사이클 공지')} · ${a.cycle}</summary><p data-user-text>${E(a.text)}</p></details>`).join('')}<div class="ca-modules">${[['challenges','MMCampaignChallenges'],['battle','MMCampaignBattle'],['economy','MMCampaignEconomy'],['operations','MMCampaignOperations']].map(([key,api])=>window[api]?.render?`<details class="ca-module" data-ca-section="${key}" ${key==='challenges'?'open':''}><summary>${L(...({challenges:['1. Choose battle opponents','1. 대전 상대 정하기'],battle:['2. Battle preparation & results','2. 전투 준비·결과 입력'],economy:['3. Income & post-cycle actions','3. 수입·종료 후 정리'],operations:['4. Trading, captives & map','4. 거래·포로·지도 관리']}[key]))}</summary><div>${moduleNote(key)}${window[api].render(c)}</div></details>`:'').join('')}</div><div class="actions ca-footer-actions">${button('core','announce','Publish cycle announcement','사이클 공지',editable?'':'disabled','small')}${button('core','guide','Campaign feature guide','캠페인 기능 안내','','small')}</div></section>`;}
function refresh(){if(typeof campaign!=='function'||data.view!=='campaign'||data.campaignTab==='session-detail')return;const c=campaign(),host=document.querySelector('.cp-campaign-page .stack');if(!c||!host)return;let root=host.querySelector(':scope > .ca-console');if(!root){host.insertAdjacentHTML('afterbegin',panel(c));root=host.querySelector(':scope > .ca-console');}for(const n of document.querySelectorAll('.cp-campaign-page .ca-console button'))if(locks.has(c.id)){if(!n.dataset.caBusy)n.dataset.caWasDisabled=String(n.disabled);n.disabled=true;n.dataset.caBusy='true';}else if(n.dataset.caBusy){n.disabled=n.dataset.caWasDisabled==='true';delete n.dataset.caBusy;delete n.dataset.caWasDisabled;}window.UKI18n?.refresh(root);}
window.addEventListener('click',event=>{const node=event.target.closest?.('[data-ca-module]');if(!node||node.disabled)return;event.preventDefault();event.stopImmediatePropagation();const c=campaign();if(!c)return;const module=node.dataset.caModule,action=node.dataset.caAction;let task;if(module==='core'){
 if(action==='deadlines')return deadlineDialog(c);if(action==='receipts')return showReceipts(c);if(action==='announce')task=announce(c);if(action==='guide'){window.open('/reports/campaign-automation.html','_blank','noopener');return;}if(action==='reverse'){modal(T('Reverse settlement','정산 취소 확인'),`<p class="wide">${L('Reverse this recorded operation? Overlapping later changes block reversal; the original receipt remains.','이 정산을 취소하고 변경 전으로 되돌릴까요? 이후 변경 사항과 겹치면 취소할 수 없습니다. 이전 정산 내역은 보관됩니다.')}</p>`,'Reverse',()=>reverse(c,node.dataset.caId));return;}
 }else task=window[{challenges:'MMCampaignChallenges',economy:'MMCampaignEconomy',operations:'MMCampaignOperations',battle:'MMCampaignBattle',preparation:'MMCampaignPreparation'}[module]]?.handle?.(action,c,node.dataset);
 Promise.resolve(task).catch(error=>notify(error.message,true));},true);
window.MMCampaignAutomation={state,cycle,phase,canEdit,canManageOwn,die,apply,reverse,receipt:getReceipt,receipts,loadReceipts,modal,button,notify,timeRemaining,reminders,panel,refresh,operationKey,busy:c=>locks.has(c.id),copy};
const prior=render;render=function(...args){const result=prior.apply(this,args);refresh();return result;};
new MutationObserver(()=>{if(!queued){queued=true;queueMicrotask(()=>{queued=false;refresh();});}}).observe(document.getElementById('app'),{childList:true,subtree:true});
let ticking=false;setInterval(()=>{if(ticking||data.view!=='campaign')return;const c=campaign(),d=c&&state(c).deadlines?.[String(cycle(c))];if(!c||!window.MMCampaignPermissions?.canArbitrate(c)||!d?.autoAdvance||!d.report||Date.now()<Date.parse(d.report)||!window.MMCampaignSchedule?.info(c)||window.MMCampaignChallenges?.pending(c)?.length||(c.sessions||[]).some(s=>!['Completed','Cancelled'].includes(s.status)&&(!s.cycle||Number(s.cycle)===cycle(c)))||document.querySelector('.modal-bg'))return;ticking=true;const next=document.querySelector('[data-campaign-schedule="advance"]');next?.click();setTimeout(()=>{ticking=false},500);},30000);
})();
